package com.promeia.music;
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import org.json.*;
final class Net {
 static String enc(String s){try{return URLEncoder.encode(s,"UTF-8");}catch(Exception e){throw new IllegalStateException(e);}}
 static byte[] get(String url,int limit)throws Exception{URL u=new URL(url);if(!"https".equals(u.getProtocol()))throw new IOException("Solo se permiten enlaces HTTPS");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","PromeiaMusic/1.0 (Android)");c.setInstanceFollowRedirects(false);try{int status=c.getResponseCode();if(status!=200)throw new IOException("Servicio HTTP "+status);try(InputStream in=c.getInputStream()){return Store.readAll(in,limit);}}finally{c.disconnect();}}
 static File downloadAudio(String url,File dir)throws Exception{URL u=new URL(url);if(!"https".equals(u.getProtocol()))throw new IOException("Solo HTTPS");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","PromeiaMusic/1.0 (Android)");File f=null;try{if(c.getResponseCode()!=200)throw new IOException("Usa el enlace HTTPS directo al archivo (sin redirecciones)");String mime=c.getContentType();if(mime==null||!mime.toLowerCase(java.util.Locale.ROOT).startsWith("audio/"))throw new IOException("El enlace no devuelve un archivo de audio");String name=Store.clean(android.net.Uri.parse(url).getLastPathSegment()==null?"Audio":android.net.Uri.parse(url).getLastPathSegment());if(!name.toLowerCase(java.util.Locale.ROOT).matches(".*\\.(mp3|m4a|aac|flac|ogg|opus|wav|amr)$")){String ext=mime.contains("flac")?".flac":mime.contains("wav")?".wav":mime.contains("mp4")?".m4a":mime.contains("ogg")?".ogg":mime.contains("aac")?".aac":".mp3";name+=ext;}if(!dir.mkdirs()&&!dir.isDirectory())throw new IOException("No se pudo crear caché");f=new File(dir,name);long total=0;try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){total+=n;if(total>150L*1024*1024)throw new IOException("Límite de 150 MB");out.write(b,0,n);}}return f;}catch(Exception e){if(f!=null)f.delete();throw e;}finally{c.disconnect();}}
 static String text(String url)throws Exception{return new String(get(url,4*1024*1024),StandardCharsets.UTF_8);}
 static JSONArray youtube(String q,String key)throws Exception{return new JSONObject(text("https://www.googleapis.com/youtube/v3/search?part=snippet&type=video&maxResults=20&videoCategoryId=10&q="+enc(q)+"&key="+enc(key))).getJSONArray("items");}
 static JSONObject lyrics(Store.Song s)throws Exception{JSONArray a=new JSONArray(text("https://lrclib.net/api/search?track_name="+enc(s.title)+"&artist_name="+enc(s.artist)));if(a.length()==0)throw new IOException("No se encontraron letras");JSONObject best=a.getJSONObject(0);double score=Double.MAX_VALUE;for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);double d=Math.abs(x.optDouble("duration",0)-s.duration/1000.0)+(x.optString("trackName").equalsIgnoreCase(s.title)?0:30)+(x.optString("artistName").equalsIgnoreCase(s.artist)?0:30);if(d<score){score=d;best=x;}}return best;}
}
